import{_ as t,o as e,c as o,ai as l}from"./chunks/framework.scx6l_IK.js";const s=JSON.parse('{"title":"炼神还虚","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-炼神还虚.md","filePath":"50-概念资料/dict-炼神还虚.md","lastUpdated":1778155802000}'),r={name:"50-概念资料/dict-炼神还虚.md"};function i(u,a,c,d,h,n){return e(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="炼神还虚" tabindex="-1">炼神还虚 <a class="header-anchor" href="#炼神还虚" aria-label="Permalink to &quot;炼神还虚&quot;">​</a></h1><blockquote><p>传统：丹道</p></blockquote><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p>炼神还虚是丹道&quot;三关&quot;中的最高阶段——神（精神能量）达到圆满，与&quot;虚&quot;（道的本体）合一。了空居士的解释很直白：就是彻底的大彻大悟。</p><h2 id="了空居士原话" tabindex="-1">了空居士原话 <a class="header-anchor" href="#了空居士原话" aria-label="Permalink to &quot;了空居士原话&quot;">​</a></h2><blockquote><p>&quot;炼神还虚就是到了最高的境界了——你的神和虚空融为一体，分不清哪里是你，哪里是虚空。&quot;</p></blockquote><blockquote><p>&quot;炼神还虚其实就是明心见性、天人合一。到了这个地步，禅宗的明心见性和丹道的还虚是一回事。&quot;</p></blockquote><blockquote><p>&quot;一滴水与大海融为一体——到底是大海得到一滴水，还是一滴水得到了大海？这就是炼神还虚的境界。&quot;</p></blockquote><h2 id="了空居士的独特观点" tabindex="-1">了空居士的独特观点 <a class="header-anchor" href="#了空居士的独特观点" aria-label="Permalink to &quot;了空居士的独特观点&quot;">​</a></h2><p>了空居士融合了禅宗和丹道，认为&quot;炼神还虚&quot;就是佛教说的&quot;明心见性&quot;、&quot;常寂光土&quot;。<strong>万法归宗，到了最高的境界都是一样的。</strong></p><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-炼精化气">炼精化气</a> — 第一关</li><li><a href="/50-概念资料/dict-炼气化神">炼气化神</a> — 第二关</li><li><a href="/50-概念资料/dict-涅槃">涅槃</a> — 炼神还虚相当于佛教的涅槃</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-天人合一">天人合一</a> — 炼神还虚的体验</li><li><a href="/10-核心模型/model-性命双修">性命双修</a> — 三关的总框架</li></ul>',14)])])}const _=t(r,[["render",i]]);export{s as __pageData,_ as default};
